{
 "id": "answer-sheet-bubble-scan",
 "name": "Halftone Read Line",
 "idea": "A fine graphite dot grid in three matte tone steps drifts slowly upward on near-black. As each row crosses a thin red read line, one dot in that row swells into a solid red mark with a short eased fill, then cools to a soft ink tone above the line, which leaves a calm one-mark-per-row trail.",
 "use": [
  "progress",
  "loading",
  "stepper"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;   // canvas size in pixels
uniform float u_time;        // seconds since start
uniform vec3 u_c0;           // surface, fills most of the frame
uniform vec3 u_c1;           // ink
uniform vec3 u_c2;           // accent
uniform vec3 u_c3;           // support
float h(float n){return fract(sin(n*127.1+3.7)*43758.5453);}
float h2(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
vec2 p=(gl_FragCoord.xy-0.5*u_resolution)/u_resolution.y;
float ar=u_resolution.x/u_resolution.y;
float aa=0.75/u_resolution.y;
float t=u_time;
float s=0.036;
float sp=0.012;
float rl=-0.14;
vec3 col=u_c0*(0.96+0.06*(p.y+0.5));
vec2 g=vec2(p.x,p.y+t*sp)/s;
vec2 id=floor(g);
vec2 f=(fract(g)-0.5)*s;
float d=length(f);
float cx=(id.x+0.5)*s;
float u=clamp(cx/ar+0.5,0.0,1.0);
float lv=floor(u*3.99)/3.0;
float r=s*(0.1+0.09*lv);
float by=(id.y+0.5)*s-t*sp;
float fd=smoothstep(-0.5,-0.36,p.y)*(1.0-smoothstep(0.3,0.48,p.y));
float rd=exp(-abs(by-rl)*40.0);
float dt=1.0-smoothstep(r-aa,r+aa,d);
col=mix(col,mix(u_c0,u_c3,0.2+0.16*lv+0.12*rd),dt*fd);
float n=max(floor(0.5*ar/s)-1.0,2.0);
float pk=1.0+floor(h(id.y)*n);
float ch=1.0-step(0.5,abs(id.x-pk));
float k=clamp((by-rl+0.004)/0.05,0.0,1.0);
float q=1.0-k;
float e=1.0-q*q*q+0.12*sin(k*3.1416)*k;
float rr=mix(r,s*0.34,e);
float fm=(1.0-smoothstep(rr-aa,rr+aa,d))*ch*step(0.001,k)*fd;
float a=1.0-smoothstep(rl+0.05,rl+0.26,by);
float gr=h2(floor(gl_FragCoord.xy))-0.5;
vec3 fc=mix(mix(u_c0,u_c1,0.42),u_c2,a);
col=mix(col,fc*(1.0+0.06*gr),fm);
float bm=0.3+0.7*smoothstep(-0.5*ar,0.35*ar,p.x);
col+=u_c2*exp(-abs(p.y-rl)*70.0)*0.06*bm;
float ln=1.0-smoothstep(0.0006,0.0006+2.0*aa,abs(p.y-rl));
col=mix(col,u_c2,ln*0.7*bm);
col+=gr*0.025;
col*=1.0-0.18*dot(p,p);
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#16181a",
  "#fbfaf5",
  "#d8432e",
  "#7a7f84"
 ],
 "reduced": {
  "kind": "fade",
  "at": 6,
  "ms": 400,
  "note": "A still graphite dot grid with a thin red read line and one marked dot per row above it."
 },
 "cardIds": [
  "exam-answer-sheet"
 ],
 "lensIds": [],
 "styles": [
  "retro-pixel-halftone"
 ]
}
```
